int x = 5, y = 3, z = 2;

// Precedence: * higher than +
int std_order = x + y * z;    // Evaluates: x + (y * z) = 11

// Parentheses override precedence
int forced_order = (x + y) * z; // Evaluates: (x + y) * z = 16

// Associativity: Same precedence (*, /) is L->R
int assoc_LtoR = x / y * z;   // Evaluates: (x / y) * z = 1 * 2 = 2

// Associativity L->R (assignment = is R->L)
int a, b;
a = b = 10;                     // b = 10, then a = b
int result = (a * 10) + b;
int same_prec = a + b - z;      // (a + b) - z
int paren_assoc = a + (b - z);
